-- Typed JSON business tables with SQL constraints and transactional change capture.
CREATE TABLE changes(sequence INTEGER PRIMARY KEY AUTOINCREMENT,table_name TEXT NOT NULL,row_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),occurred_at TEXT NOT NULL);
CREATE TABLE operations(actor_id TEXT NOT NULL,operation_id TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,status INTEGER NOT NULL,PRIMARY KEY(actor_id,operation_id));
CREATE TABLE mutation_checks(ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE device_credentials(device_id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE);
CREATE TABLE invite_credentials(invite_id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE);
CREATE TABLE admin_sessions(id TEXT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL);
CREATE TABLE login_limits(bucket TEXT PRIMARY KEY,failures INTEGER NOT NULL,window_start INTEGER NOT NULL);
CREATE TABLE participants(id TEXT PRIMARY KEY,data TEXT NOT NULL CHECK(json_valid(data) AND json_extract(data,'$.id')=id),revision INTEGER GENERATED ALWAYS AS(json_extract(data,'$.revision')) STORED);
CREATE TRIGGER participants_insert_feed AFTER INSERT ON participants BEGIN INSERT INTO changes(table_name,row_id,data,occurred_at) VALUES('participants',NEW.id,NEW.data,json_extract(NEW.data,'$.updated_at')); END;
CREATE TRIGGER participants_update_feed AFTER UPDATE ON participants BEGIN INSERT INTO changes(table_name,row_id,data,occurred_at) VALUES('participants',NEW.id,NEW.data,json_extract(NEW.data,'$.updated_at')); END;
