CREATE TRIGGER works_update_feed AFTER UPDATE ON works BEGIN INSERT INTO changes(table_name,row_id,data,occurred_at) VALUES('works',NEW.id,NEW.data,json_extract(NEW.data,'$.updated_at')); END;
