CREATE UNIQUE INDEX participant_name_active ON participants(lower(trim(json_extract(data,'$.name')))) WHERE json_extract(data,'$.deleted_at') IS NULL;
CREATE UNIQUE INDEX version_reference_active ON versions(json_extract(data,'$.reference_url')) WHERE json_extract(data,'$.deleted_at') IS NULL AND json_extract(data,'$.reference_url') IS NOT NULL;
CREATE UNIQUE INDEX response_active_daily ON responses(json_extract(data,'$.participant_id'),json_extract(data,'$.version_id'),json_extract(data,'$.record_date')) WHERE json_extract(data,'$.deleted_at') IS NULL AND json_extract(data,'$.version_id') IS NOT NULL;
CREATE UNIQUE INDEX unresolved_active_daily ON responses(json_extract(data,'$.participant_id'),lower(trim(json_extract(data,'$.unresolved_title'))),coalesce(lower(trim(json_extract(data,'$.artist_hint'))),''),coalesce(json_extract(data,'$.reference_url'),''),json_extract(data,'$.record_date')) WHERE json_extract(data,'$.deleted_at') IS NULL AND json_extract(data,'$.version_id') IS NULL;
CREATE INDEX response_participant_date ON responses(json_extract(data,'$.participant_id'),json_extract(data,'$.record_date'));
CREATE UNIQUE INDEX alias_active_unique ON aliases(json_extract(data,'$.entity_id'),lower(trim(json_extract(data,'$.name')))) WHERE json_extract(data,'$.deleted_at') IS NULL;
CREATE UNIQUE INDEX credit_active_unique ON credits(json_extract(data,'$.version_id'),json_extract(data,'$.entity_id'),json_extract(data,'$.role')) WHERE json_extract(data,'$.deleted_at') IS NULL;
CREATE UNIQUE INDEX tag_assignment_active_unique ON tag_assignments(json_extract(data,'$.version_id'),json_extract(data,'$.tag_id')) WHERE json_extract(data,'$.deleted_at') IS NULL;
CREATE UNIQUE INDEX job_version_unique ON research_jobs(json_extract(data,'$.version_id')) WHERE json_extract(data,'$.deleted_at') IS NULL AND json_extract(data,'$.version_id') IS NOT NULL;
CREATE UNIQUE INDEX job_response_unique ON research_jobs(json_extract(data,'$.response_id')) WHERE json_extract(data,'$.deleted_at') IS NULL AND json_extract(data,'$.response_id') IS NOT NULL;
CREATE UNIQUE INDEX usage_month_unique ON usage(json_extract(data,'$.month'));
CREATE UNIQUE INDEX sync_collector_unique ON sync_status(json_extract(data,'$.collector_id'));
CREATE INDEX audit_target ON audit(json_extract(data,'$.table'),json_extract(data,'$.row_id'));
CREATE TRIGGER audit_immutable_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'immutable history'); END;
CREATE TRIGGER audit_immutable_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'immutable history'); END;
CREATE TRIGGER audit_corrections_immutable_update BEFORE UPDATE ON audit_corrections BEGIN SELECT RAISE(ABORT,'immutable history'); END;
CREATE TRIGGER audit_corrections_immutable_delete BEFORE DELETE ON audit_corrections BEGIN SELECT RAISE(ABORT,'immutable history'); END;
CREATE TRIGGER changes_immutable_update BEFORE UPDATE ON changes BEGIN SELECT RAISE(ABORT,'immutable history'); END;
CREATE TRIGGER changes_immutable_delete BEFORE DELETE ON changes BEGIN SELECT RAISE(ABORT,'immutable history'); END;
